// scripts/mint-refresh-token.mjs  (node >= 22)
import http from 'node:http';
import { OAuth2Client } from 'google-auth-library';

const client = new OAuth2Client({
  clientId: process.env.GOOGLE_OAUTH_CLIENT_ID,
  clientSecret: process.env.GOOGLE_OAUTH_CLIENT_SECRET,
  redirectUri: 'http://localhost:3000/oauth2callback',
});

const url = client.generateAuthUrl({
  access_type: 'offline',   // required to receive a refresh_token
  prompt: 'consent',        // force a new refresh_token even if previously granted
  scope: ['https://www.googleapis.com/auth/spreadsheets'],
});
console.log('Open in the owner\'s browser:\n' + url);

http.createServer(async (req, res) => {
  const code = new URL(req.url, 'http://localhost:3000').searchParams.get('code');
  if (!code) return res.end('no code');
  const { tokens } = await client.getToken(code);
  console.log('GOOGLE_OAUTH_REFRESH_TOKEN=' + tokens.refresh_token);
  res.end('Done. Close this tab.');
  process.exit(0);
}).listen(3000);
